function generarCuit(prefijo) {
    while (true) {
        let base = (prefijo || "30") + String(Math.floor(10000000 + Math.random() * 90000000));
        let factores = [5, 4, 3, 2, 7, 6, 5, 4, 3, 2];
        let sum = 0;
        for (let i = 0; i < 10; i++) sum += parseInt(base[i]) * factores[i];
        let r = sum % 11;
        if (r === 1) continue;
        return base + (r === 0 ? 0 : 11 - r);
    }
}

